parameters.jsCode:
// Code node "Decision outcome" (Run Once for All Items)
// Input: the row returned by the atomic "Claim decision" query, or an empty
// item if the proposal doesn't exist (node has alwaysOutputData on).
// Output `route`: OUTCOME.execute = run the approved action, OUTCOME.cardOnly = just update
// the card (must match OUTCOME in src/build_workflows.py). "Which action?" then picks the
// writer from `kind`.

const OUTCOME = { execute: 0, cardOnly: 1 };
const WORKING = {
  calendar_event: 'Adding…', event_move: 'Moving…', event_delete: 'Deleting…',
  task_add: 'Adding…', task_done: 'Marking done…', task_delete: 'Deleting…',
  email_unsubscribe: 'Unsubscribing…',
};

const r = $('Route update').first().json;
const row = $input.first().json || {};
const base = row.summary || 'This suggestion';

let route = OUTCOME.cardOnly;
let toast;
let editText;

if (!row.id) {
  toast = 'Suggestion not found';
  editText = `${base}\n\n⚠️ This suggestion no longer exists.`;
} else if (row.ok && row.status === 'approved') {
  route = OUTCOME.execute;
  toast = WORKING[row.kind] || 'Working…';
  editText = null; // set by "Mark executed" / "Mark failed"
} else if (row.ok && row.status === 'declined') {
  toast = 'Declined';
  editText = `${base}\n\n❌ Declined.`;
} else if (row.status === 'expired') {
  toast = 'Expired';
  editText = `${base}\n\n⌛ Expired. Ask me again if you still want it.`;
} else if (row.status === 'pending') {
  toast = 'Already being processed';
  editText = `${base}\n\n⏳ Already being processed.`;
} else {
  toast = `Already ${row.status}`;
  editText = `${base}\n\nℹ️ Already ${row.status}.`;
}

return [{
  json: {
    route, toast, editText, proposalId: r.proposalId,
    kind: row.kind || null, payload: row.payload || null, summary: base,
  },
}];

// Code nodes "Check event" and "Check task" (Run Once for All Items)
// Runs after an approved move/delete/done tap, on the event or task fetched by its STORED id.
// The card showed a title and time; if the real item no longer matches them (wrong id from
// the agent, or the item changed since), this throws and the node's error output marks the
// proposal failed. So a tap can never move, complete or delete something other than what
// the card showed. Output: { kind, payload } for the writer.

const d = $('Decision outcome').first().json;
const p = d.payload || {};
const got = $input.first().json || {};

// Same normalisation as parse_agent_output.js, so titles compare equal.
const clean = (v, max) => String(v ?? '')
  .replace(/[\u0000-\u001f\u007f]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, max);

if (d.kind === 'event_move' || d.kind === 'event_delete') {
  if (!got.id || got.status === 'cancelled') throw new Error('this event no longer exists');
  if (clean(got.summary, 120) !== p.title) throw new Error('the event title changed since the card was made');
  const want = d.kind === 'event_move' ? p.oldStart : p.start;
  const ok = got.start?.dateTime
    ? new Date(got.start.dateTime).getTime() === new Date(want).getTime()
    : got.start?.date === want;
  if (!ok) throw new Error('the event time changed since the card was made');
} else if (d.kind === 'task_done' || d.kind === 'task_delete') {
  if (!got.id || got.deleted) throw new Error('this task no longer exists');
  if (clean(got.title, 120) !== p.title) throw new Error('the task title changed since the card was made');
} else {
  throw new Error(`unexpected kind ${d.kind}`);
}

return [{ json: { kind: d.kind, payload: p } }];

// Code nodes "Check event" and "Check task" (Run Once for All Items)
// Runs after an approved move/delete/done tap, on the event or task fetched by its STORED id.
// The card showed a title and time; if the real item no longer matches them (wrong id from
// the agent, or the item changed since), this throws and the node's error output marks the
// proposal failed. So a tap can never move, complete or delete something other than what
// the card showed. Output: { kind, payload } for the writer.

const d = $('Decision outcome').first().json;
const p = d.payload || {};
const got = $input.first().json || {};

// Same normalisation as parse_agent_output.js, so titles compare equal.
const clean = (v, max) => String(v ?? '')
  .replace(/[\u0000-\u001f\u007f]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, max);

if (d.kind === 'event_move' || d.kind === 'event_delete') {
  if (!got.id || got.status === 'cancelled') throw new Error('this event no longer exists');
  if (clean(got.summary, 120) !== p.title) throw new Error('the event title changed since the card was made');
  const want = d.kind === 'event_move' ? p.oldStart : p.start;
  const ok = got.start?.dateTime
    ? new Date(got.start.dateTime).getTime() === new Date(want).getTime()
    : got.start?.date === want;
  if (!ok) throw new Error('the event time changed since the card was made');
} else if (d.kind === 'task_done' || d.kind === 'task_delete') {
  if (!got.id || got.deleted) throw new Error('this task no longer exists');
  if (clean(got.title, 120) !== p.title) throw new Error('the task title changed since the card was made');
} else {
  throw new Error(`unexpected kind ${d.kind}`);
}

return [{ json: { kind: d.kind, payload: p } }];

// Code node "Check unsubscribe" (Run Once for All Items)
// Runs after an approved email_unsubscribe tap, on the Gmail message fetched by its STORED id.
// It throws (→ the node's error output marks the proposal failed) unless:
//   - the message still exists and its sender is the address shown on the card, and
//   - it carries an RFC 8058 one-click unsubscribe: "List-Unsubscribe-Post: List-Unsubscribe=One-Click"
//     plus an https link in "List-Unsubscribe".
// The link comes from the email headers only, never from the body or the agent. mailto
// links are never used (that would send an email). Output: { kind, payload, url, host }
// for "One-click unsubscribe", which POSTs the fixed one-click body to `url`.
//
// Network guard (the URL is untrusted): https only, port 443, no credentials, a public-looking
// DNS name (no IP literal, no single-label or local names such as "postgres" or "n8n").
// The HTTP node follows no redirects and validates TLS, so a name that resolves to a
// private address still cannot reach a stack service (none serves a valid cert for it).

const d = $('Decision outcome').first().json;
const p = d.payload || {};
const got = $input.first().json || {};

if (d.kind !== 'email_unsubscribe') throw new Error(`unexpected kind ${d.kind}`);
if (!got.id || got.id !== p.messageId) throw new Error('this email no longer exists');

const fromAddr = String(got.from?.value?.[0]?.address || '').trim().toLowerCase();
if (!fromAddr || fromAddr !== p.from) throw new Error('the sender changed since the card was made');

// n8n's Gmail "get" (simple: false) gives headers as { 'list-unsubscribe': 'List-Unsubscribe: <...>' }:
// lower-case keys, raw header lines. Accept a bare value too.
const headers = {};
for (const [k, v] of Object.entries(got.headers || {})) headers[k.toLowerCase()] = v;
function header(name) {
  const v = headers[name];
  if (v == null) return '';
  const s = (Array.isArray(v) ? v.join(', ') : String(v)).replace(/\s+/g, ' ').trim();
  return s.toLowerCase().startsWith(name + ':') ? s.slice(name.length + 1).trim() : s;
}

const NO_ONE_CLICK = "this sender has no one-click unsubscribe, use Gmail's Unsubscribe button instead";
if (header('list-unsubscribe-post').toLowerCase() !== 'list-unsubscribe=one-click') throw new Error(NO_ONE_CLICK);

// Strict shape, checked without the URL class (not a Code-node global): https, a host of
// letters/digits/dots/hyphens only (so no user:pass@, %-escapes, backslashes or [IPv6]),
// optional :443, then a path / query starting with / ? or #.
const HTTPS_URL = /^https:\/\/([A-Za-z0-9.-]+)(?::(\d{1,5}))?([/?#][^\s<>"\\]*)?$/;
const DNS_NAME = /^(?=.{4,253}$)[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)+$/;
const BLOCKED_HOST = /(?:^|\.)(?:localhost|localdomain|local|internal|lan|home\.arpa|test|invalid|example)$/;
function safeUrl(s) {
  if (s.length > 2048) return null;
  const m = HTTPS_URL.exec(s);
  if (!m || (m[2] && m[2] !== '443')) return null;
  const host = m[1].toLowerCase();
  // The top-level label must start with a letter: this refuses every numeric or hex IPv4
  // spelling (127.0.0.1, 2130706433, 0x7f.1) that an HTTP client would turn into an address.
  const tld = host.slice(host.lastIndexOf('.') + 1);
  if (!DNS_NAME.test(host) || !/^[a-z]/.test(tld) || /^0x/.test(tld) || BLOCKED_HOST.test(host)) return null;
  return { url: s, host };
}

const links = [...header('list-unsubscribe').matchAll(/<([^<>\s]+)>/g)].map(m => m[1]);
const https = links.filter(l => /^https:/i.test(l));
if (!https.length) throw new Error(NO_ONE_CLICK);
const target = safeUrl(https[0]);
if (!target) throw new Error('the unsubscribe link looks unsafe, use Gmail\'s Unsubscribe button instead');

return [{ json: { kind: d.kind, payload: p, url: target.url, host: target.host } }];

// Code node "Undo outcome" (Run Once for All Items)
// Input: the row returned by the atomic "Claim undo" query, or an empty item if the
// proposal doesn't exist (node has alwaysOutputData on).
// Output `route`: UNDO.run = reverse it ("Undo which?" picks by kind), UNDO.cardOnly = just
// update the message (must match UNDO in src/build_workflows.py).

const UNDO = { run: 0, cardOnly: 1 };

const r = $('Route update').first().json;
const row = $input.first().json || {};
const base = row.summary || 'This action';
const taskId = String(row.result?.id || '');

let route = UNDO.cardOnly;
let toast;
let editText;

if (!row.id) {
  toast = 'Not found';
  editText = `${base}\n\n⚠️ This action no longer exists.`;
} else if (row.ok && /^[A-Za-z0-9_-]{1,128}$/.test(taskId)) {
  route = UNDO.run;
  toast = 'Undoing…';
  editText = null; // set by "Mark undone" / "Mark undo failed"
} else if (row.ok) {
  // Claimed, but there is no task id to reverse: report it (the row stays 'undone').
  toast = 'Cannot undo';
  editText = `${base}\n\n⚠️ Could not undo it: no task id was saved. Fix it in Google Tasks.`;
} else if (row.status === 'undone') {
  toast = 'Already undone';
  editText = `${base}\n\nℹ️ Already undone.`;
} else if (row.status === 'executed') {
  toast = 'Too late to undo';
  editText = `${base}\n\n⌛ Undo is only possible for 24 hours. Change it in Google Tasks.`;
} else {
  toast = 'Nothing to undo';
  editText = `${base}\n\nℹ️ Nothing to undo (${row.status}).`;
}

return [{
  json: { route, toast, editText, proposalId: r.proposalId, kind: row.kind || null, result: row.result || null },
}];

